cd /app && python3 - <<'PY'
import json, subprocess, sys
def run(s):
    p=subprocess.run([sys.executable,'/app/submission/bridge.py'],input=json.dumps(s).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    return json.loads(p.stdout)
def H(sid,f): return {'sid':sid,'type':'headers','fields':f}
def F(sid): return {'sid':sid,'type':'fin'}
def base(m,s,a,p): return [[":method",m],[":scheme",s],[":authority",a],[":path",p]]
r=run({'routes':{'http://a.test':'o'},'events':[H(0,base('GET','http','A.TEST:00080','/')),F(0)]})
print('http80', r['streams'][0]['status'], r['streams'][0]['cache_key'])
r=run({'routes':{'http://a.test:8080':'o'},'events':[H(0,base('GET','http','a.test:08080','/')),F(0)]})
print('http8080', r['streams'][0]['status'], r['streams'][0]['cache_key'])
PY
